// A DSM from a point cloud: the highest point in each post.
export function dsmFromPoints(cloud, spacing = 1) {
  const { minX, minY, maxX, maxY } = cloud.bounds;
  const width = Math.ceil((maxX - minX) / spacing) + 1;
  const height = Math.ceil((maxY - minY) / spacing) + 1;
  const grid = new Float32Array(width * height).fill(NaN);
  for (const [x, y, z] of cloud.points) {
    const i = Math.round((maxY - y) / spacing) * width + Math.round((x - minX) / spacing);
    if (!(grid[i] >= z)) grid[i] = z;
  }
  return { width, height, spacing, grid };
}
